   }

   private static @Nullable String getLatestSingleplayerWorld(final LevelStorageSource levelSource) {
      try {
         List<LevelSummary> levels = levelSource.loadLevelSummaries(levelSource.findLevelCandidates()).get();
         if (levels.isEmpty()) {
